// Generated by scripts/sync-precedents.mjs — do not edit by hand.
// Source of truth: cases/<slug>/{case.json,README.md,scope.md,docs/{method,defense}.md,...}
// Run `node scripts/sync-precedents.mjs` after editing a precedent package.
// Case studies themselves live in src/content/docs/cases/<slug>/ and load lazily.
// Precedent bodies are NOT inlined: they ship under dist/assets/cases/<slug>/ and load on demand.

export interface PrecedentDoc {
	/** Package-relative file name, e.g. `docs/method.md`. Read it with readPrecedentDoc. */
	readonly id: string;
}

export interface PrecedentSource {
	/** Where the package was derived from, e.g. `seep-kit 2.0`. */
	readonly library: string;
	/** Upstream entry the digest was written from, e.g. `Tool/cases/项目J`. */
	readonly entry: string;
}

export interface PrecedentTool {
	readonly id: string;
	/** File name inside the package's tools/ directory. */
	readonly entry: string;
	readonly purpose: string;
	readonly args: readonly string[];
	readonly expect: string;
}

export interface PrecedentToolkit {
	/** Interpreter family: python, powershell or node. */
	readonly runtime: string;
	readonly platforms: readonly string[];
	readonly tools: readonly PrecedentTool[];
}

export interface ShippedPrecedent {
	readonly slug: string;
	readonly title: string;
	readonly summary: string;
	/** Lower-case fragments the query is matched against. */
	readonly signals: readonly string[];
	/** Preset to start from when the package is copied into a real case. */
	readonly preset: string;
	/** Field-journal documents this precedent is derived from. */
	readonly fieldNotes: readonly string[];
	/** Document-library ids holding the full case study, read with read_doc. */
	readonly caseDocs: readonly string[];
	/** Present when the package was derived from an upstream case library. */
	readonly source?: PrecedentSource;
	/** Runnable tools the package ships; empty only if the package is text-only. */
	readonly tools: PrecedentToolkit;
	readonly docs: readonly PrecedentDoc[];
}

